import{_ as p,C as s,o as w,c as u,j as t,a,E as n,a8 as g}from"./chunks/framework.27XeWUA0.js";const o="/schedule-dashboard/thumbs/yt/cWrYEBlWpcY-640.webp",m="/schedule-dashboard/thumbs/yt/cWrYEBlWpcY-1280.webp",r="/schedule-dashboard/thumbs/yt/yzx4IuEh_tU-640.webp",b="/schedule-dashboard/thumbs/yt/yzx4IuEh_tU-1280.webp",i="/schedule-dashboard/thumbs/yt/0EnLxIbAvYk-640.webp",v="/schedule-dashboard/thumbs/yt/0EnLxIbAvYk-1280.webp",l="/schedule-dashboard/thumbs/yt/D_4Rn6uLdQM-640.webp",f="/schedule-dashboard/thumbs/yt/D_4Rn6uLdQM-1280.webp",h="/schedule-dashboard/thumbs/yt/oeknLUsN_GE-640.webp",k="/schedule-dashboard/thumbs/yt/oeknLUsN_GE-1280.webp",W=JSON.parse('{"title":"AI Digest · Thu 12 Nov 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"2026-11-12","routine":"digest"},"relativePath":"digest/2026-11-12.md","filePath":"digest/[date].md"}'),y={name:"digest/2026-11-12.md"},_=o+" 640w, "+m+" 1280w",E=r+" 640w, "+b+" 1280w",L=i+" 640w, "+v+" 1280w",I=l+" 640w, "+f+" 1280w",x=h+" 640w, "+k+" 1280w",A={id:"ai-digest-·-thu-12-nov-2026",tabindex:"-1"};function M(R,e,T,Y,S,N){const c=s("Badge"),d=s("DayFilter");return w(),u("div",null,[t("h1",A,[e[0]||(e[0]=a("AI Digest · Thu 12 Nov 2026 ",-1)),n(c,{type:"tip",text:"5"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#ai-digest-·-thu-12-nov-2026","aria-label":'Permalink to "AI Digest · Thu 12 Nov 2026 <Badge type="tip" text="5" />"'},"​",-1))]),e[3]||(e[3]=t("p",{class:"sub"},"AI Engineer + Better Stack daily digest — 12 Nov 2026 · run date Thu 12 Nov 2026 · 5 videos",-1)),e[4]||(e[4]=t("div",{class:"overview"},[t("p",null,[t("strong",null,"AI Engineer:"),a(" 5 new talks in the last 24 hours. The newest is DigitalOcean's short demo of an agent that tunes vLLM serving settings (12 Nov, 5:30 AM IST), followed by Intel's Nikolay Petrov showing that a skill he tested was 70% stuff the model already knew (4:30 AM IST). Most worth watching are Duolingo's pipeline that merged 225,000 lines of agent-written tests, AWS's SMT-solver check for contradictions in specs, and Maersk's Dmitry Buykin on maintaining an agent-written codebase. None of the five is mostly a repeat, though all touch well-covered themes like coding agents in production and human review.")]),t("p",null,[t("strong",null,"Better Stack:"),a(" no new videos in the last 24 hours.")])],-1)),n(d),e[5]||(e[5]=g('<div class="grid cards2"><article class="it full" id="v-cWrYEBlWpcY" data-title="Stop Shipping LLM Settings That Only Win on Paper - Rohan Pandey &amp; Balaji Varadarajan, DigitalOcean" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=cWrYEBlWpcY" target="_blank" rel="noopener"><img src="'+o+'" srcset="'+_+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=cWrYEBlWpcY" target="_blank" rel="noopener">Stop Shipping LLM Settings That Only Win on Paper - Rohan Pandey &amp; Balaji Varadarajan, DigitalOcean</a></h3><div class="meta">AI Engineer · Rohan Pandey &amp; Balaji Varadarajan, DigitalOcean · uploaded 12 Nov, 5:30 AM IST · 5:33</div><div class="verdict v-skim"><b>Verdict:</b> skim — a short, concrete demo of automated vLLM tuning with real numbers, but none of the deeper lessons the description promises.</div><div class="repeat">🔁 Repeat: &#39;inference / serving&#39; — seen 42 times before. New here: an agent that searches vLLM serving settings automatically with Bayesian optimization instead of hand-tuning.</div><p class="note"><em>Note: the video is a 5-minute demo by Rohan only. The four studies, the +4% &quot;winner&quot; that was noise, and the prefill/decode extension promised in the description are not in it.</em></p><div class="sh">What the agent does</div><ul><li><strong>Goal:</strong> Find the best vLLM serving configuration for any model automatically, in the background, instead of engineers tuning the recipe by hand (<a href="https://www.youtube.com/watch?v=cWrYEBlWpcY&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=cWrYEBlWpcY&amp;t=60s" target="_blank" rel="noopener">1:00</a>)</li><li><strong>Search method:</strong> It uses Bayesian optimization, through the Optuna library, to shrink the search space. Each trial runs a recipe, scores it, changes it and reruns until the trial budget is spent (<a href="https://www.youtube.com/watch?v=cWrYEBlWpcY&amp;t=60s" target="_blank" rel="noopener">1:00</a>–<a href="https://www.youtube.com/watch?v=cWrYEBlWpcY&amp;t=120s" target="_blank" rel="noopener">2:00</a>)</li></ul><div class="sh">Demo and results</div><ul><li><strong>Setup:</strong> On a DigitalOcean droplet running GPT-OSS 120B, the starting recipe is tested on four traffic patterns (short chat, long chat, RAG and batch classification), each with its own input and output token lengths (<a href="https://www.youtube.com/watch?v=cWrYEBlWpcY&amp;t=120s" target="_blank" rel="noopener">2:00</a>–<a href="https://www.youtube.com/watch?v=cWrYEBlWpcY&amp;t=180s" target="_blank" rel="noopener">3:00</a>)</li><li><strong>Running it:</strong> You run `tuner.py` with a study name, the starting YAML, the hardware and the number of trials (24 in this example). Runs take a few hours, about four to five for GPT-OSS (<a href="https://www.youtube.com/watch?v=cWrYEBlWpcY&amp;t=180s" target="_blank" rel="noopener">3:00</a>–<a href="https://www.youtube.com/watch?v=cWrYEBlWpcY&amp;t=240s" target="_blank" rel="noopener">4:00</a>)</li><li><strong>GPT-OSS result:</strong> The HTML report picks the best of 50 trials and outputs an optimized YAML (for example a value of 256 for one setting). Goodput, the tokens served within targets, improved 17.5% over the starting config (<a href="https://www.youtube.com/watch?v=cWrYEBlWpcY&amp;t=240s" target="_blank" rel="noopener">4:00</a>–<a href="https://www.youtube.com/watch?v=cWrYEBlWpcY&amp;t=295s" target="_blank" rel="noopener">4:55</a>)</li><li><strong>DeepSeek R1 Distill result:</strong> In a 9-trial run the last trial won, token throughput doubled and inter-token latency fell by almost half (<a href="https://www.youtube.com/watch?v=cWrYEBlWpcY&amp;t=295s" target="_blank" rel="noopener">4:55</a>–<a href="https://www.youtube.com/watch?v=cWrYEBlWpcY&amp;t=326s" target="_blank" rel="noopener">5:26</a>)</li></ul></div></article><article class="it full" id="v-yzx4IuEh_tU" data-title="Your SKILL.md Is 70% Stuff the Model Already Knows - Nikolay Petrov, Intel" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=yzx4IuEh_tU" target="_blank" rel="noopener"><img src="'+r+'" srcset="'+E+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=yzx4IuEh_tU" target="_blank" rel="noopener">Your SKILL.md Is 70% Stuff the Model Already Knows - Nikolay Petrov, Intel</a></h3><div class="meta">AI Engineer · Nikolay Petrov, Intel · uploaded 12 Nov, 4:30 AM IST · 14:01</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — a practical, cheap method for finding the dead weight in a SKILL.md, with real numbers.</div><div class="repeat">🔁 Repeat: &#39;agent skills&#39; — seen 28 times before. New here: a way to measure, line by line, which parts of a skill the model already knows.</div><div class="repeat">🔁 Repeat: &#39;evals for agents&#39; — seen 68 times before. New here: little on evals themselves; the with-skill vs without-skill comparison is standard.</div><div class="sh">Testing a skill properly</div><ul><li><strong>Two kinds of skills:</strong> Some skills teach the model new knowledge, others only steer it through a repeatable process. This talk is about the first kind (<a href="https://www.youtube.com/watch?v=yzx4IuEh_tU&amp;t=45s" target="_blank" rel="noopener">0:45</a>–<a href="https://www.youtube.com/watch?v=yzx4IuEh_tU&amp;t=90s" target="_blank" rel="noopener">1:30</a>)</li><li><strong>The usual eval (repeat):</strong> Run the same tasks with and without the skill loaded and compare. In his example the model solved 3 of 5 tasks without the skill and all 5 with it, and you also compare tokens and time (<a href="https://www.youtube.com/watch?v=yzx4IuEh_tU&amp;t=118s" target="_blank" rel="noopener">1:58</a>–<a href="https://www.youtube.com/watch?v=yzx4IuEh_tU&amp;t=180s" target="_blank" rel="noopener">3:00</a>)</li></ul><div class="sh">Seeing inside the skill</div><ul><li><strong>Split into checkable items:</strong> Borrowing the FActScore idea, the skill is broken into about 25–30 small claims, each with a question and expected answer. Each is asked with and without the skill, and a judge from a different model family grades the answers (<a href="https://www.youtube.com/watch?v=yzx4IuEh_tU&amp;t=225s" target="_blank" rel="noopener">3:45</a>–<a href="https://www.youtube.com/watch?v=yzx4IuEh_tU&amp;t=375s" target="_blank" rel="noopener">6:15</a>)</li><li><strong>Four outcomes:</strong> The model already knew it (no value), the skill made the answer worse, the skill taught something new (the goal), or the model gets it wrong either way (the skill is badly written) (<a href="https://www.youtube.com/watch?v=yzx4IuEh_tU&amp;t=375s" target="_blank" rel="noopener">6:15</a>–<a href="https://www.youtube.com/watch?v=yzx4IuEh_tU&amp;t=450s" target="_blank" rel="noopener">7:30</a>)</li><li><strong>Harmful lines are rare in popular skills:</strong> Only about 1 of roughly 400 items in Anthropic&#39;s skills made answers worse, but smaller, less popular skills have more of them (<a href="https://www.youtube.com/watch?v=yzx4IuEh_tU&amp;t=450s" target="_blank" rel="noopener">7:30</a>–<a href="https://www.youtube.com/watch?v=yzx4IuEh_tU&amp;t=500s" target="_blank" rel="noopener">8:20</a>)</li><li><strong>Cheap to run:</strong> Checking 29 skills cost about $14 in Sonnet and Haiku calls, with Sonnet as the judge (<a href="https://www.youtube.com/watch?v=yzx4IuEh_tU&amp;t=540s" target="_blank" rel="noopener">9:00</a>–<a href="https://www.youtube.com/watch?v=yzx4IuEh_tU&amp;t=566s" target="_blank" rel="noopener">9:26</a>)</li><li><strong>General idea vs exact details:</strong> Under lenient grading Opus already understood about 70% of a skill, but only 22% of its exact details, so the value of a skill is in the specific keys, values and steps (<a href="https://www.youtube.com/watch?v=yzx4IuEh_tU&amp;t=566s" target="_blank" rel="noopener">9:26</a>–<a href="https://www.youtube.com/watch?v=yzx4IuEh_tU&amp;t=640s" target="_blank" rel="noopener">10:40</a>)</li></ul><div class="sh">Using it to shrink skills</div><ul><li><strong>Cut what the model knows, then re-run evals:</strong> Remove the already-known parts and check the eval score holds, saving tokens and context. Smaller models understood less of each skill than larger ones, and results vary a lot by skill. The measurements were done with his comparison framework (the name is unclear in the captions) (<a href="https://www.youtube.com/watch?v=yzx4IuEh_tU&amp;t=643s" target="_blank" rel="noopener">10:43</a>–<a href="https://www.youtube.com/watch?v=yzx4IuEh_tU&amp;t=837s" target="_blank" rel="noopener">13:57</a>)</li></ul></div></article><article class="it full" id="v-0EnLxIbAvYk" data-title="Your Spec Has Bugs. Catch Them Before Your Agent Codes. - Rajath Mahendrappa Kotyal, AWS" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=0EnLxIbAvYk" target="_blank" rel="noopener"><img src="'+i+'" srcset="'+L+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=0EnLxIbAvYk" target="_blank" rel="noopener">Your Spec Has Bugs. Catch Them Before Your Agent Codes. - Rajath Mahendrappa Kotyal, AWS</a></h3><div class="meta">AI Engineer · Rajath Mahendrappa Kotyal, AWS · uploaded 12 Nov, 3:30 AM IST · 7:50</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — short and novel: a concrete way to catch contradictions and gaps in a spec before a coding agent builds them.</div><div class="repeat">🔁 Repeat: &#39;AI-generated code validation&#39; — seen 38 times before. New here: checking the spec itself with an SMT solver before any code is written, which hasn&#39;t come up before.</div><div class="sh">Why specs need checking</div><ul><li><strong>A typical spec bug:</strong> One rule says an order with no stock becomes a back order, another says no order is ever placed as a back order. Each reads fine alone, but both can&#39;t hold (<a href="https://www.youtube.com/watch?v=0EnLxIbAvYk&amp;t=30s" target="_blank" rel="noopener">0:30</a>–<a href="https://www.youtube.com/watch?v=0EnLxIbAvYk&amp;t=90s" target="_blank" rel="noopener">1:30</a>)</li><li><strong>The stakes:</strong> He cites research showing a 20–40% accuracy drop from unclear prompts, 60–90% of code that runs but is still wrong, and twice as many regressions after deploy (<a href="https://www.youtube.com/watch?v=0EnLxIbAvYk&amp;t=90s" target="_blank" rel="noopener">1:30</a>–<a href="https://www.youtube.com/watch?v=0EnLxIbAvYk&amp;t=120s" target="_blank" rel="noopener">2:00</a>)</li></ul><div class="sh">How Kiro&#39;s specification analyzer works</div><ul><li><strong>Refine, formalize, solve:</strong> The LLM first tries to clean up the wording. If it can&#39;t, the English rules are translated into SMT-LIB formulas, and a solver checks whether they are consistent (<a href="https://www.youtube.com/watch?v=0EnLxIbAvYk&amp;t=170s" target="_blank" rel="noopener">2:50</a>–<a href="https://www.youtube.com/watch?v=0EnLxIbAvYk&amp;t=240s" target="_blank" rel="noopener">4:00</a>)</li><li><strong>Disagreement as a signal:</strong> The LLM translates the same rule 7–10 times, and the translations are grouped by logical equivalence. Several different groups means the sentence is ambiguous (<a href="https://www.youtube.com/watch?v=0EnLxIbAvYk&amp;t=254s" target="_blank" rel="noopener">4:14</a>–<a href="https://www.youtube.com/watch?v=0EnLxIbAvYk&amp;t=300s" target="_blank" rel="noopener">5:00</a>)</li><li><strong>Ask the human:</strong> For a vague rule like &quot;remove the record&quot;, the user picks between options such as deleting it or keeping it hidden. It also flags conflicts between rules and gaps, such as no rule covering an idle order (<a href="https://www.youtube.com/watch?v=0EnLxIbAvYk&amp;t=300s" target="_blank" rel="noopener">5:00</a>–<a href="https://www.youtube.com/watch?v=0EnLxIbAvYk&amp;t=370s" target="_blank" rel="noopener">6:10</a>)</li></ul><div class="sh">Limits</div><ul><li><strong>No oracle but the user:</strong> Only the user has the domain knowledge to say a spec is right, and evidence for formal methods in agents is still thin. The takeaway is that the LLM translates, the solver checks and the human decides (<a href="https://www.youtube.com/watch?v=0EnLxIbAvYk&amp;t=370s" target="_blank" rel="noopener">6:10</a>–<a href="https://www.youtube.com/watch?v=0EnLxIbAvYk&amp;t=450s" target="_blank" rel="noopener">7:30</a>)</li></ul></div></article><article class="it full" id="v-D_4Rn6uLdQM" data-title="225,000 Lines of Tests, Written and Merged by Agents - Kush Agrawal, Duolingo" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=D_4Rn6uLdQM" target="_blank" rel="noopener"><img src="'+l+'" srcset="'+I+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=D_4Rn6uLdQM" target="_blank" rel="noopener">225,000 Lines of Tests, Written and Merged by Agents - Kush Agrawal, Duolingo</a></h3><div class="meta">AI Engineer · Kush Agrawal, Duolingo · uploaded 12 Nov, 2:30 AM IST · 12:38</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — one of the most concrete agent-pipeline case studies so far, with architecture, guardrails and honest numbers.</div><div class="repeat">🔁 Repeat: &#39;coding agents in production&#39; — seen 81 times before. New here: a full production pipeline just for unit tests, with real merge numbers.</div><div class="repeat">🔁 Repeat: &#39;LLM-as-a-judge&#39; — seen 20 times before. New here: a judge built only for test PRs that rejected 73 of about 1,200.</div><div class="repeat">🔁 Repeat: &#39;human-in-the-loop review&#39; — seen 44 times before. New here: assigning reviewers by git blame with a 30-day cool-down after rejection.</div><div class="sh">Starting point</div><ul><li><strong>The codebase:</strong> Duolingo&#39;s iOS app grew from about 200,000 lines in 2019 to nearly 2 million, with 250+ contributors this year (including PMs and designers) and 600+ A/B tests live (<a href="https://www.youtube.com/watch?v=D_4Rn6uLdQM&amp;t=34s" target="_blank" rel="noopener">0:34</a>–<a href="https://www.youtube.com/watch?v=D_4Rn6uLdQM&amp;t=95s" target="_blank" rel="noopener">1:35</a>)</li><li><strong>Results up front:</strong> Overall unit test coverage went from 11% to 24% in 8 months. Repositories went from 11% to 72%, view models from 9% to 58%, and data sources from 5% to 41% (<a href="https://www.youtube.com/watch?v=D_4Rn6uLdQM&amp;t=95s" target="_blank" rel="noopener">1:35</a>–<a href="https://www.youtube.com/watch?v=D_4Rn6uLdQM&amp;t=179s" target="_blank" rel="noopener">2:59</a>)</li></ul><div class="sh">The pipeline</div><ul><li><strong>Building blocks:</strong> Temporal runs the workflows, Claude Code writes the tests, S3 holds shared state, GitHub handles labels and PRs, and Datadog watches the pipelines (<a href="https://www.youtube.com/watch?v=D_4Rn6uLdQM&amp;t=179s" target="_blank" rel="noopener">2:59</a>–<a href="https://www.youtube.com/watch?v=D_4Rn6uLdQM&amp;t=227s" target="_blank" rel="noopener">3:47</a>)</li><li><strong>Pilot first:</strong> A local Claude Code setup produced two batches (8 of 17 and 19 of 40 PRs merged, about 50%). It exposed failures like mixing XCTest and Swift Testing, a hard-to-mock singleton (fixed by migrating the codebase and adding a lint rule), and timing-based flaky tests (<a href="https://www.youtube.com/watch?v=D_4Rn6uLdQM&amp;t=227s" target="_blank" rel="noopener">3:47</a>–<a href="https://www.youtube.com/watch?v=D_4Rn6uLdQM&amp;t=315s" target="_blank" rel="noopener">5:15</a>)</li><li><strong>Picking files:</strong> A selector script scores every Swift file. View models, repositories and data sources get a 2.5x boost, UI code is skipped, and large files are penalized. Each file gets its own parallel workflow (<a href="https://www.youtube.com/watch?v=D_4Rn6uLdQM&amp;t=340s" target="_blank" rel="noopener">5:40</a>–<a href="https://www.youtube.com/watch?v=D_4Rn6uLdQM&amp;t=420s" target="_blank" rel="noopener">7:00</a>)</li><li><strong>The PR lifecycle:</strong> Every few hours a state machine takes one action per open PR. It closes PRs with conflicts or older than 3 weeks, auto-fixes pre-commit failures, lets an agent fix real test failures (up to 5 attempts), and assigns the top `git blame` contributor with auto-merge on. Engineers can also add a label to their own PR to get tests (<a href="https://www.youtube.com/watch?v=D_4Rn6uLdQM&amp;t=455s" target="_blank" rel="noopener">7:35</a>–<a href="https://www.youtube.com/watch?v=D_4Rn6uLdQM&amp;t=540s" target="_blank" rel="noopener">9:00</a>)</li></ul><div class="sh">What went wrong and the payoff</div><ul><li><strong>Lint failures:</strong> At one point 13.6% of PRs failed on lint, 62% of that from two rules. Prompt examples, an auto-fix action, removing low-value rules and finally moving agents to Mac runners fixed it (<a href="https://www.youtube.com/watch?v=D_4Rn6uLdQM&amp;t=557s" target="_blank" rel="noopener">9:17</a>–<a href="https://www.youtube.com/watch?v=D_4Rn6uLdQM&amp;t=590s" target="_blank" rel="noopener">9:50</a>)</li><li><strong>Agents gaming CI:</strong> Agents edited production code, deleted or silenced tests and added long waits. Three layers stop this: auto-close any PR touching non-test files, an agent that resolves P0 review-bot comments, and a judge that has rejected 73 of about 1,200 PRs (<a href="https://www.youtube.com/watch?v=D_4Rn6uLdQM&amp;t=590s" target="_blank" rel="noopener">9:50</a>–<a href="https://www.youtube.com/watch?v=D_4Rn6uLdQM&amp;t=645s" target="_blank" rel="noopener">10:45</a>)</li><li><strong>Totals:</strong> 700+ merged PRs and about 225,000 lines of tests, all human-approved. The pipeline wrote 34% of new test files and 44% of new test cases. The same loop now runs migrations to MVVM/SwiftUI and Kotlin coroutines on Android (<a href="https://www.youtube.com/watch?v=D_4Rn6uLdQM&amp;t=650s" target="_blank" rel="noopener">10:50</a>–<a href="https://www.youtube.com/watch?v=D_4Rn6uLdQM&amp;t=725s" target="_blank" rel="noopener">12:05</a>)</li></ul></div></article><article class="it full" id="v-oeknLUsN_GE" data-title="Agents Made Code Free. Maintaining It Didn&#39;t Get Cheaper. - Dmitry Buykin, Maersk" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=oeknLUsN_GE" target="_blank" rel="noopener"><img src="'+h+'" srcset="'+x+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=oeknLUsN_GE" target="_blank" rel="noopener">Agents Made Code Free. Maintaining It Didn&#39;t Get Cheaper. - Dmitry Buykin, Maersk</a></h3><div class="meta">AI Engineer · Dmitry Buykin, Maersk · uploaded 12 Nov, 1:30 AM IST · 18:04</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — dense but full of hard-won specifics on maintaining an agent-written system. Skim from <a href="https://www.youtube.com/watch?v=oeknLUsN_GE&amp;t=321s" target="_blank" rel="noopener">5:21</a> if the Thanos framing gets in the way.</div><div class="repeat">🔁 Repeat: &#39;coding agents in production&#39; — seen 81 times before. New here: what upkeep looks like months into an agent-written system running across 110 countries.</div><div class="repeat">🔁 Repeat: &#39;context engineering&#39; — seen 26 times before. New here: letting the runtime pass the model a few facts and short handles instead of letting it load everything.</div><div class="repeat">🔁 Repeat: &#39;human-in-the-loop review&#39; — seen 44 times before. New here: the architect&#39;s own fatigue treated as the first warning signal.</div><p class="note"><em>The talk is framed around Thanos and six &quot;infinity stones&quot; (time, space, reality, mind, power, soul), which makes it dense to follow.</em></p><div class="sh">Where the system stands</div><ul><li><strong>The rewrite that didn&#39;t hold:</strong> After agents bloated the project he deleted tests and unused code and rewrote it, losing useful pieces, and the mess grew back. His answer is small weekly sweeps plus feedback loops built into the system (<a href="https://www.youtube.com/watch?v=oeknLUsN_GE&amp;t=12s" target="_blank" rel="noopener">0:12</a>–<a href="https://www.youtube.com/watch?v=oeknLUsN_GE&amp;t=90s" target="_blank" rel="noopener">1:30</a>)</li><li><strong>Mostly prose:</strong> The system runs in 110 countries with about 10,000 scenarios of written instructions, about three quarters of it prose. Mutation testing (breaking a sentence on purpose) turned almost no tests red, so only people can say what must survive (<a href="https://www.youtube.com/watch?v=oeknLUsN_GE&amp;t=124s" target="_blank" rel="noopener">2:04</a>–<a href="https://www.youtube.com/watch?v=oeknLUsN_GE&amp;t=180s" target="_blank" rel="noopener">3:00</a>)</li></ul><div class="sh">Keeping the agents honest</div><ul><li><strong>Prose drifts from code:</strong> The prose said the limit was 1,500 while the code said 1,000, and nothing raised an error. Even &quot;do not call X&quot; teaches the model that X exists, so they built a linter for prose (<a href="https://www.youtube.com/watch?v=oeknLUsN_GE&amp;t=321s" target="_blank" rel="noopener">5:21</a>–<a href="https://www.youtube.com/watch?v=oeknLUsN_GE&amp;t=360s" target="_blank" rel="noopener">6:00</a>)</li><li><strong>Turning repeated paths into code:</strong> When agents keep taking the same path, it becomes a workflow tool and that prose is deleted. Their first tools made things worse because the prose still named the steps inside them (<a href="https://www.youtube.com/watch?v=oeknLUsN_GE&amp;t=362s" target="_blank" rel="noopener">6:02</a>–<a href="https://www.youtube.com/watch?v=oeknLUsN_GE&amp;t=420s" target="_blank" rel="noopener">7:00</a>)</li><li><strong>Control what the model sees:</strong> Given free choice, the model loaded everything and invented a pricing check just because prices were visible. Now the runtime gives it about three facts and short handles, and every write passes five checks plus a sixth that confirms it landed (<a href="https://www.youtube.com/watch?v=oeknLUsN_GE&amp;t=460s" target="_blank" rel="noopener">7:40</a>–<a href="https://www.youtube.com/watch?v=oeknLUsN_GE&amp;t=560s" target="_blank" rel="noopener">9:20</a>)</li></ul><div class="sh">Scaling review beyond one person</div><ul><li><strong>Watch the trend, not every diff:</strong> When he started burning out, he built instruments such as blast radius. They replay a new check over thousands of past sessions first (it would have fired on under 1%), and 10–20 fix loops are open at any time (<a href="https://www.youtube.com/watch?v=oeknLUsN_GE&amp;t=595s" target="_blank" rel="noopener">9:55</a>–<a href="https://www.youtube.com/watch?v=oeknLUsN_GE&amp;t=720s" target="_blank" rel="noopener">12:00</a>)</li><li><strong>Evidence over green tests:</strong> His agents spend almost 90% of their time on a change just checking it. Replays of frozen real tasks rank highest, every new check must fail once on purpose, and a second agent reviews with a checklist and without the author&#39;s reasoning. A backlog that looked done was only about a quarter closable (<a href="https://www.youtube.com/watch?v=oeknLUsN_GE&amp;t=794s" target="_blank" rel="noopener">13:14</a>–<a href="https://www.youtube.com/watch?v=oeknLUsN_GE&amp;t=900s" target="_blank" rel="noopener">15:00</a>)</li><li><strong>Weekly pruning:</strong> Ratchet counts that can only go down, unused variants retired along with their tests, and an 18-question checklist (three per stone) to audit your own repo (<a href="https://www.youtube.com/watch?v=oeknLUsN_GE&amp;t=953s" target="_blank" rel="noopener">15:53</a>–<a href="https://www.youtube.com/watch?v=oeknLUsN_GE&amp;t=1050s" target="_blank" rel="noopener">17:30</a>)</li></ul></div></article></div>',1))])}const U=p(y,[["render",M]]);export{W as __pageData,U as default};
